import heapq


def dependency_solver(data, preference, order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {r["version"]: r for r in versions}
            for name, versions in packages.items()}
    choices = []
    for name in names:
        allowed = [v for v in sorted(rows[name])
                   if v not in blocked.get(name, [])
                   and (name not in pins or pins[name] == v)]
        choices.append([-1] + allowed)

    best = None
    best_vector = None
    for values in product(*choices):
        selected = {name: v for name, v in zip(names, values) if v != -1}
        if any(name not in selected or not lo <= selected[name] <= hi
               for name, (lo, hi) in data["roots"].items()):
            continue

        edges = {name: [] for name in selected}
        valid = True
        for name, version in selected.items():
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                if target not in selected or not dep["min"] <= selected[target] <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        # Installed packages must be precisely the dependency closure of roots.
        reached = set()
        stack = list(data["roots"])
        while stack:
            node = stack.pop()
            if node in reached:
                continue
            reached.add(node)
            stack.extend(edges.get(node, []))
        if reached != set(selected):
            continue

        finished, active = set(), set()
        def visit(node):
            if node in active:
                return False
            if node in finished:
                return True
            active.add(node)
            if any(not visit(child) for child in edges.get(node, [])):
                return False
            active.remove(node)
            finished.add(node)
            return True
        if not all(visit(node) for node in selected):
            continue

        vector = tuple(selected.get(n, -1) for n in sorted(names, reverse=(order == "descending")))
        if best is None or (vector < best_vector if preference == "minimum" else vector > best_vector):
            best, best_vector = selected, vector
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _c01(d): return dependency_solver(d, "minimum", "descending")
def _c02(d): return dependency_solver(d, "maximum", "ascending")
def _c03(d): return dependency_solver(d, "minimum", "ascending")
def _c04(d): return dependency_solver(d, "maximum", "descending")
def _c05(d): return dependency_solver(d, "minimum", "descending")


def _round(n, mode):
    return (n + 5000) // 10000 if mode == "half_up" else n // 10000


def _c06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        seq = event.get("sequence", 0)
        if seq > cutoff:
            continue
        ident = event.get("id", "anonymous:" + str(pos))
        key = (seq, event.get("revision", 0), pos)
        if ident not in winners or key > winners[ident][0]:
            winners[ident] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        tax = _round(raw * event.get("tax_bp", 0), mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _c07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None
    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        idset = set(ids)
        if idset & blocked or not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not lo <= counts.get(group, 0) <= hi
               for group, (lo, hi) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda j: (j["start"], j["end"], j["id"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if best_ids is None or value > best_value or (value == best_value and ids > best_ids):
            best_ids, best_value = ids, value
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _c08(data):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    bit = {node: 1 << i for i, node in enumerate(required)}
    initial_mask = bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    dist = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, left = heapq.heappop(queue)
        state = (node, mask, left)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full and left == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], left)]
            if left:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), left - 1))
            for duration, next_left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, next_left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


